// A loopback-only workspace host. Model execution still requires the visible workspace.
class NativeCore {
    static readonly JavaScriptSerializer Json = new JavaScriptSerializer {MaxJsonLength=100*1024*1024,RecursionLimit=160};
    static readonly object Gate=new object();
    static readonly Dictionary<string,object> Session=new Dictionary<string,object>();
    static readonly HashSet<string> ActiveRequests=new HashSet<string>();
    static string Root=AppDomain.CurrentDomain.BaseDirectory, Data, Token, Owner="", Origin;
    static DateTime LeaseUntil=DateTime.MinValue;
    static TcpListener Listener;
    static int Port;
    static string Encode(object v){lock(Json)return Json.Serialize(v);}
    static Dictionary<string,object> Decode(string v){lock(Json)return Json.Deserialize<Dictionary<string,object>>(v);}
    static string Str(Dictionary<string,object> v,string k){object x;return v.TryGetValue(k,out x)&&x!=null?Convert.ToString(x):"";}
    static string Hash(string x){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(x))).Replace("-","").ToLowerInvariant();}
    static string FileFor(string area,string key){return Path.Combine(Data,area+"-"+Hash(key)+".dat");}
    static byte[] Protect(byte[] b){return ProtectedData.Protect(b,Encoding.UTF8.GetBytes("AI-Relay local workspace v1"),DataProtectionScope.CurrentUser);}
    static byte[] Unprotect(byte[] b){return ProtectedData.Unprotect(b,Encoding.UTF8.GetBytes("AI-Relay local workspace v1"),DataProtectionScope.CurrentUser);}
    static void Atomic(string path,byte[] bytes){string tmp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllBytes(tmp,bytes);if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
    static object Read(string area,string key){lock(Gate){if(area=="session"){object value;return Session.TryGetValue(key,out value)?value:null;}string f=FileFor(area,key);if(!File.Exists(f))return null;var b=File.ReadAllBytes(f);if(area=="local"&&key=="relayApiSecrets")b=Unprotect(b);lock(Json)return Json.DeserializeObject(Encoding.UTF8.GetString(b));}}
    static void Write(string area,string key,object value){lock(Gate){if(area=="session"){Session[key]=value;return;}var b=Encoding.UTF8.GetBytes(Encode(value));if(area=="local"&&key=="relayApiSecrets")b=Protect(b);Atomic(FileFor(area,key),b);}}
    static void Remove(string area,string key){lock(Gate){if(area=="session")Session.Remove(key);else{string f=FileFor(area,key);if(File.Exists(f))File.Delete(f);}}}
    static void RestrictDirectory(){Directory.CreateDirectory(Data);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);acl.AddAccessRule(new FileSystemAccessRule(WindowsIdentity.GetCurrent().User,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));new DirectoryInfo(Data).SetAccessControl(acl);}
    static void Open(string url){var browser="chrome";var profile="Default";var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"Google\Chrome\User Data");try{var b=Decode(File.ReadAllText(Path.Combine(Root,"browser-profile.json")));browser=Str(b,"browser");profile=Str(b,"profile");folder=Str(b,"dataDir");}catch{}if(!Regex.IsMatch(profile,@"^[\p{L}\p{N}_ -]{1,80}$")||folder.IndexOfAny(new[]{'"','\r','\n'})>=0)throw new Exception("浏览器配置无效。");string rel=browser=="edge"?@"Microsoft\Edge\Application\msedge.exe":@"Google\Chrome\Application\chrome.exe";foreach(var home in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)}){var p=Path.Combine(home,rel);if(File.Exists(p)){Process.Start(new ProcessStartInfo(p,"--user-data-dir=\""+Path.GetFullPath(folder).TrimEnd('\\')+"\" --profile-directory=\""+profile+"\" --app=\""+url+"\""){UseShellExecute=true});return;}}throw new Exception("没有找到 Chrome 或 Edge。");}
    static string LaunchURL(){return Origin+"/app.html?launch="+Token;}
    [STAThread] static void Main(string[] args){try{bool noOpen=false;string info="";Data=Path.Combine(Root,"data");for(int i=0;i<args.Length;i++){if(args[i]=="--no-open")noOpen=true;else if(args[i]=="--data"&&i+1<args.Length)Data=Path.GetFullPath(args[++i]);else if(args[i]=="--info"&&i+1<args.Length)info=Path.GetFullPath(args[++i]);}RestrictDirectory();bool created;using(var mutex=new Mutex(true,"Local\\AI-Relay-Core-"+Hash(Data).Substring(0,24),out created)){if(!created){var previous=Decode(Encoding.UTF8.GetString(Unprotect(File.ReadAllBytes(Path.Combine(Data,"runtime.dat")))));int pid=Convert.ToInt32(previous["pid"]);using(var p=Process.GetProcessById(pid)){if(!String.Equals(p.MainModule.FileName,Application.ExecutablePath,StringComparison.OrdinalIgnoreCase)||p.StartTime.ToUniversalTime().Ticks.ToString()!=Str(previous,"started"))throw new Exception("旧的启动记录无效，请重新打开应用。");}if(!noOpen)Open(Str(previous,"url"));return;}
        var random=new byte[32];using(var r=RandomNumberGenerator.Create())r.GetBytes(random);Token=BitConverter.ToString(random).Replace("-","").ToLowerInvariant();Listener=new TcpListener(IPAddress.Loopback,0);Listener.Start(32);Port=((IPEndPoint)Listener.LocalEndpoint).Port;Origin="http://127.0.0.1:"+Port;var run=new {pid=Process.GetCurrentProcess().Id,started=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks.ToString(),url=LaunchURL()};Atomic(Path.Combine(Data,"runtime.dat"),Protect(Encoding.UTF8.GetBytes(Encode(run))));if(info!="")Atomic(info,Encoding.UTF8.GetBytes(Encode(run)));if(!noOpen)Open(LaunchURL());while(true){var c=Listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(delegate{Handle(c);});}}}catch(Exception e){try{File.WriteAllText(Path.Combine(Data,"startup-error.txt"),e.Message,Encoding.UTF8);}catch{}if(Array.IndexOf(args,"--no-open")<0)MessageBox.Show("本机工作台启动失败："+e.Message,"AI 互审",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
    static void Send(NetworkStream s,int status,string type,byte[] body,string extra){var h="HTTP/1.1 "+status+" "+(status==200?"OK":"Request rejected")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\nContent-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; worker-src 'self' blob:; connect-src 'self' https: http://127.0.0.1:* http://localhost:*; frame-ancestors 'none'; object-src 'none'; base-uri 'none'\r\n"+extra+"\r\n";var b=Encoding.ASCII.GetBytes(h);s.Write(b,0,b.Length);s.Write(body,0,body.Length);}
    static void Reply(NetworkStream s,int status,object value){Send(s,status,"application/json; charset=utf-8",Encoding.UTF8.GetBytes(Encode(value)),"");}
    static void Handle(TcpClient c){using(c){c.ReceiveTimeout=15000;c.SendTimeout=15000;using(var s=c.GetStream()){try{var hb=new List<byte>();int tail=0;while(hb.Count<16384){int x=s.ReadByte();if(x<0)return;hb.Add((byte)x);tail=(tail<<8)|x;if(tail==0x0d0a0d0a)break;}if(tail!=0x0d0a0d0a){Reply(s,400,new{ok=false,error="请求头过长。"});return;}var lines=Encoding.ASCII.GetString(hb.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);var parts=lines[0].Split(' ');if(parts.Length!=3){Reply(s,400,new{ok=false});return;}var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);for(int i=1;i<lines.Length;i++){int colon=lines[i].IndexOf(':');if(colon>0){var key=lines[i].Substring(0,colon);if(headers.ContainsKey(key)){Reply(s,400,new{ok=false});return;}headers[key]=lines[i].Substring(colon+1).Trim();}}
        string host;if(!headers.TryGetValue("Host",out host)||host!="127.0.0.1:"+Port){Reply(s,403,new{ok=false});return;}string raw=parts[1];Uri u;if(!Uri.TryCreate(Origin+raw,UriKind.Absolute,out u)||u.Authority!=host){Reply(s,400,new{ok=false});return;}string path=Uri.UnescapeDataString(u.AbsolutePath);string auth;bool proof=headers.TryGetValue("X-Relay-Proof",out auth)&&auth==Token;string cookie;bool cookieOK=headers.TryGetValue("Cookie",out cookie)&&Regex.IsMatch(cookie,@"(?:^|;\s*)relay_session="+Token+@"(?:;|$)");bool launch=path=="/app.html"&&u.Query=="?launch="+Token&&parts[0]=="GET";if(!proof&&!cookieOK&&!launch){Reply(s,403,new{ok=false,error="工作台连接已失效，请从桌面快捷方式重新打开。"});return;}
        if(path=="/rpc"&&parts[0]=="POST"){if(headers.ContainsKey("Transfer-Encoding")){Reply(s,400,new{ok=false});return;}string length;int n;if(!headers.TryGetValue("Content-Length",out length)||!Int32.TryParse(length,out n)||n<2||n>80*1024*1024){Reply(s,413,new{ok=false,error="请求大小超出上限。"});return;}var b=new byte[n];int at=0;while(at<n){int count=s.Read(b,at,n-at);if(count==0)throw new IOException();at+=count;}var request=Decode(Encoding.UTF8.GetString(b));string origin;if(!proof||(headers.TryGetValue("Origin",out origin)&&origin!=Origin&&!(Str(request,"op")=="proof"&&origin=="chrome-extension://ecjeppfncoeigfaiojgpmpppgmlkbcil"))){Reply(s,403,new{ok=false,error="请求来源无效。"});return;}string client;headers.TryGetValue("X-Relay-Client",out client);Reply(s,200,new{ok=true,value=RPC(request,client??"")});return;}
        if(parts[0]!="GET"){Reply(s,405,new{ok=false});return;}if(path.IndexOf('\0')>=0||path.IndexOf('\\')>=0){Reply(s,403,new{ok=false});return;}string ext=Path.GetExtension(path).ToLowerInvariant();string mime;var types=new Dictionary<string,string>{{".html","text/html; charset=utf-8"},{".js","text/javascript; charset=utf-8"},{".mjs","text/javascript; charset=utf-8"},{".css","text/css; charset=utf-8"},{".png","image/png"},{".ico","image/x-icon"},{".svg","image/svg+xml"},{".bcmap","application/octet-stream"},{".pfb","application/octet-stream"},{".ttf","font/ttf"},{".woff","font/woff"},{".woff2","font/woff2"}};if(!types.TryGetValue(ext,out mime)){Reply(s,404,new{ok=false});return;}string staticRoot=Path.GetFullPath(Path.Combine(Root,"extension"))+Path.DirectorySeparatorChar;string file=Path.GetFullPath(Path.Combine(staticRoot,path.TrimStart('/').Replace('/',Path.DirectorySeparatorChar)));if(!file.StartsWith(staticRoot,StringComparison.OrdinalIgnoreCase)||!File.Exists(file)){Reply(s,404,new{ok=false});return;}Send(s,200,mime,File.ReadAllBytes(file),launch?"Set-Cookie: relay_session="+Token+"; HttpOnly; SameSite=Strict; Path=/\r\n":"");
    }catch(Exception e){try{Reply(s,400,new{ok=false,error=e is IOException?"本机连接中断。":e.Message});}catch{}}}}}
    static object RPC(Dictionary<string,object> r,string client){string op=Str(r,"op");if(op=="health")return new{native=true,version="0.8.1"};if(!Regex.IsMatch(client,@"^[a-zA-Z0-9-]{1,80}$"))throw new Exception("工作台标识无效。");lock(Gate){if(op=="lease"){if(Owner==client||LeaseUntil<DateTime.UtcNow){Owner=client;LeaseUntil=DateTime.UtcNow.AddSeconds(20);return true;}return false;}if(op=="release"){if(Owner==client){Owner="";LeaseUntil=DateTime.MinValue;}return true;}if(op=="proof")return Owner==client&&LeaseUntil>DateTime.UtcNow;}
        string area=Str(r,"area"),key=Str(r,"key");if(op=="read"){if(!new List<string>{"local","session","materials","files","requests"}.Contains(area))throw new Exception("存储区域无效。");return Read(area,key);}lock(Gate){if(Owner!=client||LeaseUntil<DateTime.UtcNow)throw new Exception("此工作台当前只读，请在正在使用的窗口操作。");}
        if(op=="write"||op=="remove"){lock(Gate){if(Owner!=client||LeaseUntil<DateTime.UtcNow)throw new Exception("工作台使用权已变化。");if(!new List<string>{"local","session","materials","files"}.Contains(area)||key.Length>160||key.Length==0)throw new Exception("存储区域或记录名称无效。");if(op=="write")Write(area,key,r["value"]);else Remove(area,key);return true;}}
        if(op=="api")return API(r,client);throw new Exception("不支持的本机操作。");}
    static object API(Dictionary<string,object> r,string client){string id=Str(r,"id");if(!Regex.IsMatch(id,@"^[a-zA-Z0-9:_-]{1,240}$"))throw new Exception("请求标识无效。");lock(Gate){if(Owner!=client||LeaseUntil<DateTime.UtcNow)throw new Exception("工作台使用权已变化。");var old=Read("requests",id) as Dictionary<string,object>;if(old!=null){if(Str(old,"status")=="done")return old["response"];throw new Exception("该请求已尝试发送，状态尚未确认；不会重复调用接口。");}Write("requests",id,new{status="pending",at=DateTime.UtcNow.ToString("o")});ActiveRequests.Add(id);}
        try{Uri url;if(!Uri.TryCreate(Str(r,"url"),UriKind.Absolute,out url)||url.UserInfo!=""||url.Query!=""||url.Fragment!=""||!(url.Scheme=="https"||(url.Scheme=="http"&&(url.Host=="127.0.0.1"||url.Host=="localhost"))))throw new Exception("接口地址无效。");var headers=(Dictionary<string,object>)r["headers"];string authorization=Str(headers,"Authorization");if(!authorization.StartsWith("Bearer ")||authorization.IndexOfAny(new[]{'\r','\n'})>=0)throw new Exception("API Key 无效。");var request=(HttpWebRequest)WebRequest.Create(url);request.Method="POST";request.ContentType="application/json";request.AllowAutoRedirect=false;request.CookieContainer=null;request.Headers["Authorization"]=authorization;request.Proxy=null;int timeout=Math.Max(1000,Math.Min(3600000,Convert.ToInt32(r["timeout"])));request.Timeout=timeout;request.ReadWriteTimeout=timeout;ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;byte[] body=Encoding.UTF8.GetBytes(Str(r,"body"));request.ContentLength=body.Length;using(var output=request.GetRequestStream())output.Write(body,0,body.Length);HttpWebResponse response=null;try{response=(HttpWebResponse)request.GetResponse();}catch(WebException e){response=e.Response as HttpWebResponse;if(response==null)throw new Exception("API 网络连接中断，发送状态无法确认；不会自动重发。");}using(response){using(var input=response.GetResponseStream()){var output=new MemoryStream();var buffer=new byte[8192];int count;while((count=input.Read(buffer,0,buffer.Length))>0){if(output.Length+count>4*1024*1024)throw new Exception("API 返回内容超过 4 MB，状态需手动确认。");output.Write(buffer,0,count);}var result=new{status=(int)response.StatusCode,body=Encoding.UTF8.GetString(output.ToArray())};Write("requests",id,new{status="done",response=result});return result;}}
        }catch(Exception e){Write("requests",id,new{status="uncertain",error=e.Message});throw;}finally{lock(Gate)ActiveRequests.Remove(id);}}
}
